// Retail RVA 0x00584330 (435 bytes, ret 4). Places a banner in the first of
// the two BannerUI banner slots that no movie entry occupies, and returns the
// slot or -1. The banner type name comes from a game logic callee, falls back
// to BannerRohan, and is looked up in the banner type table at BannerUI+8. The
// slot's AddBanner call, the new movie entry, and the APT:BannerTimer%d text
// reset follow. BannerUI is proven by the vector at +0x30 that BannerUI.cpp
// models, so the method keeps its address in the name.

template <typename T> class StringBase
{
	friend class AsciiString;
	friend class UnicodeString;

private:
	StringBase() : m_data( 0 ) {}
	StringBase( const T *text );
	StringBase( const StringBase<T> &other );
	~StringBase();

	void *m_data;
};

class AsciiString : private StringBase<char>
{
public:
	AsciiString() : StringBase<char>() {}
	AsciiString( const char *text ) : StringBase<char>( text ) {}
	AsciiString( const AsciiString &other ) : StringBase<char>( other ) {}
	~AsciiString() {}
	AsciiString &operator=( const char *text );
	void __cdecl format( AsciiString fmt, ... );
	bool bannerIsEmpty( void ) const
	{
		return m_data == 0 || ((unsigned short *)m_data)[ 2 ] == 0;
	}
};

class UnicodeString : private StringBase<unsigned short>
{
public:
	UnicodeString( const unsigned short *text ) : StringBase<unsigned short>( text ) {}
	UnicodeString( const UnicodeString &other ) : StringBase<unsigned short>( other ) {}
	~UnicodeString() {}
};

