template <class F> static __forceinline F bannerCall( void ( *raw )() )
{
	union { void ( *raw )(); F typed; } call;
	call.raw = raw;
	return call.typed;
}

class BannerUI
{
public:
	int rva00584330( void *player );

private:
	char m_pad00[ 8 ];
	char m_types[ 0x14 ];
	char m_pad1c[ 0x14 ];
	_STL::vector<BannerMovieEntry> m_movieEntries;
};

int BannerUI::rva00584330( void *player )
{
	BfmeTaggedPair found = bfmeScanTaggedPair(
		(BfmeTaggedRecord *)m_movieEntries.m_start,
		(BfmeTaggedRecord *)m_movieEntries.m_finish,
		BfmeTaggedPair( 0, 0 ) );

	int slot = 0;
	while ( slot < 2 && found.m_bfmeRecords[ slot ] != 0 )
		++slot;
	if ( slot >= 2 )
		return -1;

	AsciiString type;
	( (BfmeThingDVB *)TheBfmeGameLogic )->bfmeGoDVBc( &type, player );
	if ( type.bannerIsEmpty() )
		type = "BannerRohan";

	BannerTypeNode *node = ( ( (BannerTypeLookup *)m_types )->*bannerCall<FindTypeCall>( j_00048bd0 ) )( type );
	if ( node == 0 )
		return -1;

	AddBanner( slot, node->m_name, node->m_label );

	BannerMovieEntry entry;
	entry.m_id = slot;
	entry.m_at18 = &node->m_name;
	m_movieEntries.push_back( entry );

	AsciiString text;
	text.format( AsciiString( "APT:BannerTimer%d" ), slot );
	g_theWindowManager->bfme_setAptText( text, UnicodeString( g_Rva01088AF4EmptyWideString ) );
	return slot;
}
